solution.code:
#include <stdio.h>
#include <string.h>

int main() {
    const char *fruits[] = {"pear", "peach", "plum", "apple"};
    int n = 4;
    for (int i = 0; i < n - 1; i++) {
        for (int j = 0; j < n - 1 - i; j++) {
            if (strcmp(fruits[j], fruits[j + 1]) > 0) {
                const char *temp = fruits[j];
                fruits[j] = fruits[j + 1];
                fruits[j + 1] = temp;
            }
        }
    }
    for (int i = 0; i < n; i++) {
        printf("%s\n", fruits[i]);
    }
    return 0;
}
